1	// Vendored verbatim from re-cinq/lore libs/shared/src (commit 4536b6c6f). Lore stays the source of truth; keep in sync.
2	/** Derives a spec/ADR's status (draft/in-progress/shipped) from its own `([validated by](test.ts#Lnn))` links rather than whoever last edited the row; shared by `lore/require-status-matches-coverage` and spec-status-upkeep FR1. */
3	import { segmentStatements, buildIntroOrdinals, classifyByHeuristic, } from "./spec-segment.js";
4	import { parseTestLinksInStatement } from "./spec-link-parser.js";
5	import { enforceTrue } from "./enforce.js";
6	/** Single walk of a doc's testable statements; `require-statement-links` reads `unlinked`, status rules read `testable`/`linked`. */
7	export function statementCoverage(content) {
8	    const statements = segmentStatements(content);
9	    const introOrdinals = buildIntroOrdinals(statements);
10	    const coverage = { testable: 0, linked: 0, unlinked: [] };
11	    for (const statement of statements) {
12	        if (classifyByHeuristic(statement, introOrdinals).testability !== "testable") {
13	            continue;
14	        }
15	        coverage.testable++;
16	        if (parseTestLinksInStatement(statement.text).length > 0) {
17	            coverage.linked++;
18	            continue;
19	        }
20	        // `Statement.line` is optional (test doubles omit it), so fall back to line 1.
21	        coverage.unlinked.push({ text: statement.text, line: statement.line ?? 1 });
22	    }
23	    return coverage;
24	}
25	/** Testable, unlinked statements — the `require-statement-links` view. */
26	export function unlinkedTestableStatements(content) {
27	    return statementCoverage(content).unlinked;
28	}
29	export function coverageTier(testable, linked) {
30	    if (testable === 0) {
31	        return "vacuous";
32	    }
33	    if (linked === 0) {
34	        return "none";
35	    }
36	    return linked < testable ? "partial" : "full";
37	}
38	const TIER_STATUS = {
39	    vacuous: null,
40	    none: "draft",
41	    partial: "in-progress",
42	    full: "shipped",
43	};
44	/** The status bucket a tier entitles a doc to claim, or `null` for `vacuous` (no testable statements to infer from). */
45	export function expectedStatus(tier) {
